import sys


class Scanner:
    def __init__(self, stream):
        self.stream = stream
        self.tokens = []
        self.index = 0

    def scan(self):
        while self.index >= len(self.tokens):
            line = self.stream.readline()
            if not line:
                return False
            self.tokens = line.split()
            self.index = 0
        return True

    def text(self):
        token = self.tokens[self.index]
        self.index += 1
        return token


writer = sys.stdout
scanner = Scanner(sys.stdin)


def next_token():
    if not scanner.scan():
        raise Exception("scan error")
    return scanner.text()


def next_int64():
    try:
        return int(next_token(), 0)
    except ValueError:
        return 0


def next_int():
    try:
        return int(next_token())
    except ValueError:
        return 0


def next_float():
